\begin{tabular}{@{}lcc@{}}
\toprule
Model & Original (60) & Reworded (120) \\
\midrule
Frozen base (no correction) & 7/60 = 11.7\% & not measured \\
\midrule
\textbf{CRN~v2} (rank~128, $\lambda{=}0.1$) & \textbf{32/60 = 53.3\%} & \textbf{52/120 = 43.3\%} \\
