\caption{Capability benchmarks ($N{=}200$ per task, except car-wash $N{=}8$). $\Delta$ is the change from the frozen base. Identical prompts and greedy decoding for all models.}
\begin{tabular}{@{}lccc@{}}
\toprule
Benchmark & Base & CRN~v2 & LoRA \\
\midrule
MMLU (knowledge) & 125/200 = 62.5\% & \textbf{125/200} ($\Delta{=}0$) & 64/200 = 32.0\% ($\Delta{=}{-}30.5$\,pp) \\
BoolQ (comprehension) & 144/200 = 72.0\% & \textbf{144/200} ($\Delta{=}0$) & 110/200 = 55.0\% ($\Delta{=}{-}17.0$\,pp) \\
Car-wash ($N{=}8$) & 6/8 = 75.0\% & \textbf{6/8} ($\Delta{=}0$) & 0/8 = 0\% ($\Delta{=}{-}75$\,pp) \\
